 using System.ComponentModel;
 using Microsoft.Extensions.AI;
 using Microsoft.Agents.AI;

 // --- Configuration -----------------------------------------------------------
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // --- Tools -------------------------------------------------------------------
 var notebook = new ResearchNotebook();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         ([Description("The search query to look up on the web")] string query) =>
         {
             return WebSearchSimulator.Search(query);
         },
         "web_search",
         "Searches the web for information on a given query and returns a list of results with titles, snippets, and URLs."),

     AIFunctionFactory.Create(
         ([Description("A concise note capturing a key finding")] string note,
          [Description("The source URL or reference for this note")] string source) =>
         {
             notebook.AddNote(note, source);
             return $"Note saved. You now have {notebook.Notes.Count} note(s).";
         },
         "take_note",
         "Saves a research note with its source for later use in the summary."),

     AIFunctionFactory.Create(
         () =>
         {
             return notebook.GetAllNotes();
         },
         "read_notes",
         "Retrieves all notes taken so far during the research session."),
 };

 // --- Agent setup -------------------------------------------------------------
 var chatClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 const string instructions = """
     You are a research agent. When given a topic:
     1. Use the web_search tool to find relevant information (perform 2-3 searches
        with different queries to get broad coverage).
     2. Use the take_note tool to record key findings with their sources.
     3. After gathering enough information, use read_notes to review everything,
        then produce a well-structured summary with source citations.
     Always cite your sources. Be thorough but concise.
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 var runOptions = new ChatClientAgentRunOptions
 {
     ChatOptions = new ChatOptions
     {
         Temperature = 0f,
         MaxOutputTokens = 2048,
     },
 };

 // --- Run ---------------------------------------------------------------------
 Console.WriteLine("╔══════════════════════════════════════╗");
 Console.WriteLine("║       AI Research Agent (MAF)        ║");
 Console.WriteLine("╚══════════════════════════════════════╝");
 Console.WriteLine();

 var topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptForTopic();

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 var session = await agent.CreateSessionAsync("research-session");

 var response = await agent.RunAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session,
     runOptions);

 Console.WriteLine("═══════════════ RESULTS ═══════════════");
 Console.WriteLine(response.Text);
 Console.WriteLine("═══════════════════════════════════════");
 Console.WriteLine($"\n📝 Total notes taken: {notebook.Notes.Count}");

 static string PromptForTopic()
 {
     Console.Write("Enter a research topic: ");
     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrWhiteSpace(topic))
     {
         Console.WriteLine("No topic provided. Using default topic.");
         topic = "the impact of large language models on software development";
     }
     return topic;
 }

 // =============================================================================
 // Supporting types
 // =============================================================================

 /// <summary>Simulates web search results for demonstration purposes.</summary>
 static class WebSearchSimulator
 {
     public static string Search(string query)
     {
         // In production, replace with a real search API (Bing, Google, Brave, etc.)
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         return $$"""
             Search results for "{{query}}":

             1. Title: "{{query}} - Overview and Key Concepts"
                URL: https://example.com/articles/{{Uri.EscapeDataString(query.Replace(' ', '-'))}}
                Snippet: Comprehensive overview of {{query}}. This article covers the main concepts,
                recent developments, and expert analysis of the current state of the field.

             2. Title: "Latest Research on {{query}}"
                URL: https://research.example.org/papers/{{Uri.EscapeDataString(query.Replace(' ', '-'))}}
                Snippet: A peer-reviewed study examining {{query}} with data from 2024-2025.
                Key findings include significant advancements and emerging trends.

             3. Title: "{{query}}: Practical Applications and Future Outlook"
                URL: https://techblog.example.com/{{Uri.EscapeDataString(query.Replace(' ', '-'))}}
                Snippet: Industry practitioners discuss real-world applications of {{query}},
                including case studies, best practices, and predictions for the next 5 years.
             """;
     }
 }

 /// <summary>Stores research notes collected by the agent.</summary>
 class ResearchNotebook
 {
     public List<(string Note, string Source, DateTime Timestamp)> Notes { get; } = [];

     public void AddNote(string note, string source)
     {
         Notes.Add((note, source, DateTime.UtcNow));
         Console.WriteLine($"  📝 Note taken: {Truncate(note, 60)}");
     }

     public string GetAllNotes()
     {
         if (Notes.Count == 0)
             return "No notes have been taken yet.";

         return string.Join("\n\n", Notes.Select((n, i) =>
             $"Note {i + 1}:\n  Content: {n.Note}\n  Source: {n.Source}"));
     }

     private static string Truncate(string text, int maxLength) =>
         text.Length <= maxLength ? text : text[..maxLength] + "...";
 }
